-- Lot 209 : payloads 241 a 270 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-187","moteur":"chatgpt","payload":"[RaccourcIA — /canmockup]\n\nMISSION\nCréer un rendu de canette commercial et fidèle au design. Respecte cylindre, sertissage et languette, préserve la face lisible. La condensation reste contrôlée et ne cache pas les mentions.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Mockup canette » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Respecte cylindre, sertissage et languette, préserve la face lisible. La condensation reste contrôlée et ne cache pas les mentions. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"540bbb92513ec6f56bca4b38779104243b2c950d68b59a5c34a6898e4ae211c9"},{"ref":"RCI-IMG-187","moteur":"claude","payload":"[RaccourcIA — /canmockup]\n\nMISSION\nCréer un rendu de canette commercial et fidèle au design. Respecte cylindre, sertissage et languette, préserve la face lisible. La condensation reste contrôlée et ne cache pas les mentions.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Mockup canette » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Respecte cylindre, sertissage et languette, préserve la face lisible. La condensation reste contrôlée et ne cache pas les mentions. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"2ead1f2627ffc27f0ab05295c7185dafca595f9e006c028931c3610245d4e5f1"},{"ref":"RCI-IMG-187","moteur":"gemini","payload":"[RaccourcIA — /canmockup]\n\nMISSION\nCréer un rendu de canette commercial et fidèle au design. Respecte cylindre, sertissage et languette, préserve la face lisible. La condensation reste contrôlée et ne cache pas les mentions.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Mockup canette » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Respecte cylindre, sertissage et languette, préserve la face lisible. La condensation reste contrôlée et ne cache pas les mentions. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"271e0b67d0de373a979f9f68a5f7699f57c9d4c4f443e5bcbde07f745d78081d"},{"ref":"RCI-IMG-195","moteur":"chatgpt","payload":"[RaccourcIA — /catalogcover]\n\nMISSION\nCréer une couverture de catalogue claire et désirable. Montre un produit héros et des indices de gamme, avec titre et saison exacts. La couverture annonce le contenu sans inventer de collection.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel message unique doit être compris en premier ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Couverture catalogue » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Montre un produit héros et des indices de gamme, avec titre et saison exacts. La couverture annonce le contenu sans inventer de collection. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve le produit, l’identité de marque fournie et tous les textes ou chiffres validés. Respecte les marges de sécurité du canal.\n\nÉVITER\nÉvite hiérarchie confuse, petit texte, faux avis, fausse réduction, CTA inventé, promesse invérifiable et surcharge. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"9871b0521d1b7f20a29aed540c78cc48c1925b3b